margin:0 0 5px;position:relative;z-index:1}.welcome p{font-size:10px;color:#d1ddd0;margin:0;position:relative;z-index:1}.welcome-tag{z-index:1;color:#d3ef77;border:1px solid rgba(211,239,119,.35);border-radius:4px;padding:8px 10px;font-size:9px;font-weight:700}.columns{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:17px}.panel{background:#fbfcf9;border:1px solid var(--line);border-radius:5px;padding:20px}.panel h3{font:700 13px 'Manrope',sans-serif;letter-spacing:0;margin:0 0 6px}.panel>p{font-size:10px;color:#7b817a;margin:0 0 18px}.shift{display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-top:1px solid #e9ebe6;font-size:10px}.shift strong{font-size:10px}.shift span{color:#81877f}.ready{padding:5px 8px;color:#386649;background:#e8f0e5;border-radius:3px;font-size:8px;font-weight:700}.task-list{display:flex;flex-direction:column;gap:9px}.task{display:flex;align-items:center;gap:11px;border:1px solid #e7e9e3;border-radius:4px;padding:11px}.task-icon{height:30px;width:30px;flex:0 0 30px;border-radius:4px;background:#e9efe5;color:var(--green);display:grid;place-items:center;font-size:14px}.task b{display:block;font-size:10px;margin-bottom:3px}.task small{font-size:9px;color:#7b817a}.task>span:last-child{margin-left:auto;color:#54805e}.bottom{margin-top:17px;background:#eef2e9;border:1px solid #dfe7d8;border-radius:4px;padding:13px 15px;color:#566151;font-size:9px;line-height:1.6}.bottom strong{color:#34543c}@media(max-width:640px){.topbar{padding:0 18px}.status{display:none}.main{padding:31px 18px}.heading{align-items:start;gap:15px;flex-direction:column}.clock{text-align:left}.columns{grid-template-columns:1fr}.welcome{align-items:start;gap:17px;flex-direction:column}.welcome:after{right:-77px}}
