<header class="topbar"><a class="brand" href="{{ route('cashier.dashboard') }}"><span class="mark">R</span> Ruang Kerja</a><div class="right"><span class="status">Sesi aktif</span><div class="avatar" aria-label="{{ auth()->user()->name }}">{{ strtoupper(substr(auth()->user()->name, 0, 1)) }}</div><form method="POST" action="{{ route('logout') }}">@csrf<button class="logout" type="submit">Keluar</button></form></div></header>
<main class="main"><section class="heading"><div><div class="eyebrow">RUANG OPERASIONAL</div><h1>Ruang kasir</h1><p>Area kerja untuk aktivitas operasional kasir.</p></div><div class="clock"><strong>{{ now()->format('H:i') }}</strong><span>{{ now()->locale('id')->translatedFormat('l, d F Y') }}</span></div></section>
